insert into data_sources ("id", "name", "publisher", "url", "kind", "methodology", "limitations", "license", "update_frequency") values ('livora-demo', 'Dados demonstrativos Partiu Morar', null, null, 'demo', 'Valores ilustrativos de ordem de grandeza, preparados pela equipe de desenvolvimento para testar a interface e os cálculos. Não foram coletados de uma fonte primária.', 'Não representam preços, salários ou indicadores reais. Não use para decisões financeiras. Serão substituídos por fontes verificadas antes do lançamento.', null, null);
insert into data_sources ("id", "name", "publisher", "url", "kind", "methodology", "limitations", "license", "update_frequency") values ('livora-editorial', 'Pesquisa editorial Partiu Morar (pendente de verificação)', null, null, 'estimate', 'Informação geral compilada pela equipe a partir de conhecimento público e de órgãos oficiais citados. Aguarda conferência individual na fonte original.', 'Pode estar desatualizada ou arredondada. Confira sempre a fonte oficial indicada antes de agir.', null, null);
insert into data_sources ("id", "name", "publisher", "url", "kind", "methodology", "limitations", "license", "update_frequency") values ('frankfurter-ecb', 'Frankfurter API (taxas de referência do Banco Central Europeu)', 'Frankfurter / Banco Central Europeu', 'https://frankfurter.dev', 'third_party', 'Taxas de referência publicadas pelo BCE em dias úteis (por volta de 16h CET) e distribuídas pela API aberta Frankfurter. Conversões entre moedas que não o euro são calculadas de forma cruzada via EUR.', 'Não são cotações de balcão nem de cartão: bancos e casas de câmbio aplicam spread e tarifas. Cobre apenas cerca de 30 moedas; fins de semana e feriados repetem a última publicação.', 'Dados públicos do BCE; API de código aberto sem chave', 'Diária (dias úteis)');
insert into data_sources ("id", "name", "publisher", "url", "kind", "methodology", "limitations", "license", "update_frequency") values ('iso-4217', 'ISO 4217 — códigos de moedas', 'International Organization for Standardization', 'https://www.iso.org/iso-4217-currency-codes.html', 'official', 'Padrão internacional de códigos de moeda.', 'Não informa valores ou cotações.', null, null);
insert into data_sources ("id", "name", "publisher", "url", "kind", "methodology", "limitations", "license", "update_frequency") values ('iana-tz', 'IANA Time Zone Database', 'IANA', 'https://www.iana.org/time-zones', 'official', 'Base de referência de fusos horários usada por sistemas operacionais e navegadores.', 'O horário de verão pode mudar por decisão de cada governo.', null, null);
insert into data_sources ("id", "name", "publisher", "url", "kind", "methodology", "limitations", "license", "update_frequency") values ('user-input', 'Informado por você', null, null, 'user', 'Valores digitados por você nas ferramentas do Partiu Morar.', 'Os resultados dependem da exatidão das informações fornecidas.', null, null);
