insert into indicators ("id", "label", "methodology", "limitations") values ('safety', 'Segurança', 'Escala 0–100, maior é mais seguro. Na versão final: índices oficiais de criminalidade por habitante, normalizados.', 'Estatísticas criminais variam muito entre bairros e entre metodologias nacionais.');
insert into indicators ("id", "label", "methodology", "limitations") values ('health', 'Saúde', 'Escala 0–100. Na versão final: indicadores como expectativa de vida e cobertura (OMS/Banco Mundial).', 'Dados nacionais podem não refletir a realidade de uma cidade específica.');
insert into indicators ("id", "label", "methodology", "limitations") values ('education', 'Educação', 'Escala 0–100. Na versão final: resultados educacionais oficiais e oferta de ensino.', 'Não considera escolas internacionais nem custos de mensalidade.');
insert into indicators ("id", "label", "methodology", "limitations") values ('mobility', 'Mobilidade', 'Escala 0–100. Na versão final: cobertura de transporte público e tempo médio de deslocamento.', 'A experiência depende muito do bairro escolhido.');
insert into indicators ("id", "label", "methodology", "limitations") values ('air', 'Qualidade do ar', 'Escala 0–100. Na versão final: média anual de PM2.5 (OMS) convertida para escala.', 'Medições podem ser esparsas e variar por estação do ano.');
insert into indicators ("id", "label", "methodology", "limitations") values ('climate', 'Clima', 'Escala 0–100. Na versão final: dias por ano em faixa de temperatura confortável.', 'Conforto climático é subjetivo; use também o gráfico mensal.');
insert into indicators ("id", "label", "methodology", "limitations") values ('internet', 'Internet e infraestrutura digital', 'Escala 0–100. Na versão final: velocidades medianas de banda larga fixa.', 'Velocidades medianas não garantem a qualidade em um endereço específico.');
insert into indicators ("id", "label", "methodology", "limitations") values ('green', 'Áreas verdes', 'Escala 0–100. Na versão final: área verde por habitante a partir de dados geográficos abertos.', 'Mapeamentos abertos podem ser incompletos.');
insert into indicators ("id", "label", "methodology", "limitations") values ('culture', 'Lazer e cultura', 'Escala 0–100. Na versão final: densidade de equipamentos culturais por habitante.', 'Quantidade não mede qualidade nem preço.');
insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('portugal', 'Portugal', 'PT', 'europa', 'EUR', array['Português']::text[], 'Possui visto específico para trabalho remoto. Fuso horário próximo ao do Reino Unido facilita trabalhar para Europa; para o Brasil a diferença é de 3 a 4 horas.', '{"language":"Português europeu, com sotaque e vocabulário diferentes do brasileiro. Inglês é comum em áreas turísticas e de tecnologia.","health":"Serviço Nacional de Saúde (SNS) público, acessível a residentes; muitos estrangeiros complementam com seguro privado.","education":"Ensino público gratuito; escolas internacionais concentradas em Lisboa e Porto.","connectivity":"Boa cobertura de fibra óptica nas áreas urbanas."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('portugal', 'Cidadãos da União Europeia, do Espaço Econômico Europeu e da Suíça têm livre circulação. Demais nacionalidades geralmente precisam de visto consular antes de pedir autorização de residência. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Visto de trabalho","description":"Para quem tem contrato ou promessa de contrato com empregador em Portugal."},{"title":"Visto para trabalho remoto (D8)","description":"Para profissionais que trabalham para empresas ou clientes fora de Portugal e comprovam renda mínima."},{"title":"Visto de rendimentos (D7)","description":"Para quem tem renda passiva ou própria regular, como aposentadoria ou aluguéis."},{"title":"Visto de estudo","description":"Para matrícula em instituição de ensino reconhecida."}]'::jsonb, '{"BR":"Brasileiros podem se beneficiar do Acordo de Mobilidade da CPLP e do Estatuto de Igualdade. Confirme as condições vigentes nos sites oficiais."}'::jsonb, null);
