insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('espanha', 'Espanha', 'ES', 'europa', 'EUR', array['Espanhol','Catalão (Catalunha)']::text[], 'Visto específico para trabalho remoto. Fuso horário da Europa Central.', '{"language":"Espanhol é essencial no dia a dia; em Barcelona, o catalão também é língua oficial e muito usado.","health":"Sistema Nacional de Saúde público para residentes que contribuem; seguro privado é exigido em algumas autorizações.","education":"Rede pública ampla; escolas bilíngues e internacionais nas capitais.","connectivity":"Uma das maiores redes de fibra óptica da Europa."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('espanha', 'Cidadãos da UE/EEE/Suíça têm livre circulação. Outras nacionalidades precisam de visto ou autorização conforme o objetivo. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Visto para nômades digitais","description":"Criado pela Lei de Startups para quem trabalha remotamente para empresas estrangeiras."},{"title":"Profissional altamente qualificado","description":"Para cargos qualificados com oferta de emprego."},{"title":"Residência não lucrativa","description":"Para quem tem meios próprios e não vai trabalhar no país."},{"title":"Estudos","description":"Para cursos em instituições autorizadas."}]'::jsonb, '{}'::jsonb, null);
