insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('alemanha', 'Alemanha', 'DE', 'europa', 'EUR', array['Alemão']::text[], 'Não possui visto específico para nômades digitais; freelancers usam o visto de trabalho autônomo.', '{"language":"Alemão é necessário para burocracia e vida cotidiana; em tecnologia, há muitas empresas que operam em inglês.","health":"Seguro de saúde é obrigatório (público ou privado); a contribuição pública é descontada do salário.","education":"Ensino público gratuito, incluindo a maioria das universidades públicas.","connectivity":"Cobertura boa nas cidades, mas fibra óptica ainda em expansão."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('alemanha', 'A Alemanha tem programas voltados a profissionais qualificados de fora da UE. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Cartão Azul da UE","description":"Para profissionais com diploma superior e oferta de emprego acima de um salário mínimo definido."},{"title":"Visto para profissionais qualificados","description":"Para pessoas com formação profissional ou acadêmica reconhecida."},{"title":"Cartão de Oportunidade (Chancenkarte)","description":"Permite procurar emprego no país com base em um sistema de pontos."},{"title":"Trabalho autônomo","description":"Para freelancers com clientes e plano de negócios."}]'::jsonb, '{}'::jsonb, null);
