insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('paises-baixos', 'Países Baixos', 'NL', 'europa', 'EUR', array['Neerlandês']::text[], 'Sem visto de nômade digital; trabalho remoto para empresa estrangeira exige outra base legal de residência.', '{"language":"Inglês é amplamente falado; o neerlandês ajuda muito na integração e em vagas fora de tecnologia.","health":"Seguro básico de saúde é obrigatório e pago à parte pelo residente.","education":"Escolas públicas gratuitas; oferta de escolas internacionais nas grandes cidades.","connectivity":"Infraestrutura digital muito desenvolvida."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('paises-baixos', 'O país atrai profissionais altamente qualificados por meio de empregadores reconhecidos pelo IND. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Migrante altamente qualificado","description":"Contratação por empregador reconhecido com salário mínimo definido."},{"title":"Cartão Azul da UE","description":"Alternativa para profissionais com diploma superior."},{"title":"Ano de orientação","description":"Para recém-formados em universidades bem classificadas procurarem emprego."}]'::jsonb, '{}'::jsonb, null);
