insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('irlanda', 'Irlanda', 'IE', 'europa', 'EUR', array['Inglês','Irlandês']::text[], 'Sem visto para nômades digitais. Sede europeia de muitas empresas de tecnologia.', '{"language":"Inglês é o idioma do dia a dia.","health":"Sistema público (HSE) com tempos de espera; seguro privado é comum entre trabalhadores.","education":"Escolas públicas, muitas de gestão religiosa; universidades bem avaliadas.","connectivity":"Boa em Dublin; variável em áreas rurais."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('irlanda', 'Cidadãos da UE/EEE/Suíça podem viver e trabalhar livremente. Para outras nacionalidades, o caminho mais comum é a autorização de trabalho. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Critical Skills Employment Permit","description":"Para profissões em falta no país, com oferta de emprego."},{"title":"General Employment Permit","description":"Para outras ocupações elegíveis com oferta de emprego."},{"title":"Estudante (Stamp 2)","description":"Permite trabalho limitado durante os estudos."}]'::jsonb, '{}'::jsonb, null);
