insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('reino-unido', 'Reino Unido', 'GB', 'europa', 'GBP', array['Inglês']::text[], 'Sem visto de nômade digital. Mesmo fuso de Portugal.', '{"language":"Inglês, com grande diversidade de sotaques.","health":"NHS público; muitos vistos exigem pagamento da Immigration Health Surcharge.","education":"Escolas públicas (state schools) gratuitas; universidades de prestígio internacional.","connectivity":"Boa cobertura urbana."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('reino-unido', 'Após o Brexit, cidadãos da UE também precisam de visto para trabalhar. O sistema funciona por pontos e vistos específicos. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Skilled Worker","description":"Oferta de emprego de empregador licenciado e salário mínimo da ocupação."},{"title":"Global Talent","description":"Para líderes ou promessas em áreas como tecnologia, ciência e artes."},{"title":"Estudante e Graduate","description":"Estudo em instituição licenciada, com possibilidade de trabalho após a formatura."}]'::jsonb, '{}'::jsonb, null);
