insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('canada', 'Canadá', 'CA', 'america-do-norte', 'CAD', array['Inglês','Francês']::text[], 'Visitantes podem trabalhar remotamente para empregador estrangeiro em situações específicas; confira as regras do IRCC.', '{"language":"Inglês predomina em Toronto; em Montreal, o francês é a língua oficial do Quebec e importante no trabalho.","health":"Sistema público provincial para residentes; pode haver carência para recém-chegados.","education":"Escolas públicas gratuitas; universidades com grande presença de estudantes internacionais.","connectivity":"Boa nas cidades, com preços de internet e celular relativamente altos."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('canada', 'O Canadá tem programas de residência permanente por pontos e diversas autorizações de trabalho e estudo. Quebec tem processo próprio de seleção. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Express Entry","description":"Sistema de pontos para residência permanente de trabalhadores qualificados."},{"title":"Programas provinciais (PNP)","description":"Províncias indicam candidatos alinhados a suas necessidades."},{"title":"Permissão de trabalho","description":"Normalmente vinculada a oferta de emprego e avaliação do mercado (LMIA)."},{"title":"Permissão de estudo","description":"Estudo em instituição designada, com trabalho limitado."}]'::jsonb, '{}'::jsonb, null);
