insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('mexico', 'México', 'MX', 'america-do-norte', 'MXN', array['Espanhol']::text[], 'Popular entre profissionais remotos que atendem os EUA, pelo fuso horário próximo.', '{"language":"Espanhol é indispensável fora de bolhas de expatriados.","health":"Sistema público (IMSS) para trabalhadores formais; rede privada ampla e mais acessível que nos EUA.","education":"Escolas públicas e grande oferta de escolas particulares bilíngues.","connectivity":"Boa em bairros centrais da capital."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('mexico', 'Muitas nacionalidades entram como turistas sem visto, mas morar ou trabalhar exige residência temporária ou permanente. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Residência temporária por solvência econômica","description":"Para quem comprova renda ou poupança mínima; usada por trabalhadores remotos."},{"title":"Residência temporária com permissão de trabalho","description":"Vinculada a oferta de empregador mexicano."},{"title":"Estudante","description":"Para cursos com duração superior a 180 dias."}]'::jsonb, '{}'::jsonb, null);
