insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('tailandia', 'Tailândia', 'TH', 'asia', 'THB', array['Tailandês']::text[], 'Um dos destinos mais procurados por trabalhadores remotos; há vistos específicos.', '{"language":"Tailandês é difícil para iniciantes; inglês funciona em áreas centrais e turísticas.","health":"Hospitais privados de padrão internacional em Bangkok; seguro saúde é altamente recomendado.","education":"Escolas internacionais em inglês nas grandes cidades, com mensalidades elevadas.","connectivity":"Internet rápida e barata nas cidades, com muitos espaços de coworking."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('tailandia', 'Trabalhar na Tailândia exige visto e autorização de trabalho específicos. Há vistos de longa permanência voltados a profissionais remotos. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Destination Thailand Visa (DTV)","description":"Voltado a trabalhadores remotos e atividades culturais, com comprovação financeira."},{"title":"Long-Term Resident (LTR)","description":"Para profissionais remotos de alta renda, aposentados e especialistas qualificados."},{"title":"Non-Immigrant B + Work Permit","description":"Para contratação por empresa tailandesa."}]'::jsonb, '{}'::jsonb, null);
