insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('japao', 'Para trabalhar é necessário um status de residência compatível com a atividade, normalmente com patrocínio de empregador. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Engenheiro/Especialista em Humanidades/Serviços Internacionais","description":"Status mais comum para profissionais com diploma contratados no Japão."},{"title":"Profissional Altamente Qualificado","description":"Sistema de pontos com benefícios de residência."},{"title":"Nômade digital (atividades designadas)","description":"Estadia de curta duração para trabalhadores remotos de alta renda de países elegíveis."}]'::jsonb, '{"BR":"Descendentes de japoneses (nikkeis) podem ter acesso a status de residência específicos. Confirme na Agência de Imigração."}'::jsonb, null);
