insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('singapura', 'Singapura', 'SG', 'asia', 'SGD', array['Inglês','Mandarim','Malaio','Tâmil']::text[], 'Não há visto de nômade digital para rendas médias; foco em profissionais contratados localmente.', '{"language":"Inglês é o idioma de trabalho e administração.","health":"Sistema eficiente e caro para estrangeiros; seguro privado é essencial.","education":"Ensino público de alto desempenho, com vagas limitadas para estrangeiros.","connectivity":"Uma das infraestruturas digitais mais avançadas do mundo."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('singapura', 'Autorizações de trabalho são concedidas pelo Ministério do Trabalho e dependem de salário, qualificação e critérios de pontuação. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Employment Pass","description":"Para profissionais e gestores com salário mínimo e avaliação COMPASS."},{"title":"S Pass","description":"Para técnicos de nível intermediário, com cotas por empresa."},{"title":"ONE Pass","description":"Para talentos de destaque em negócios, artes, ciência ou esportes."}]'::jsonb, '{}'::jsonb, null);
