insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('australia', 'Austrália', 'AU', 'oceania', 'AUD', array['Inglês']::text[], 'Sem visto de nômade digital. Fuso horário muito distante das Américas.', '{"language":"Inglês australiano.","health":"Medicare público para residentes permanentes; temporários geralmente precisam de seguro privado.","education":"Escolas públicas; estudantes internacionais pagam mensalidades.","connectivity":"Boa nas capitais; distâncias grandes encarecem a infraestrutura."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('australia', 'Programas por pontos e patrocínio de empregador; listas de ocupações qualificadas definem a elegibilidade. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Vistos qualificados independentes ou patrocinados","description":"Baseados em pontos, avaliação de competências e ocupação elegível."},{"title":"Patrocínio de empregador","description":"Contratação por empresa australiana aprovada."},{"title":"Estudante","description":"Estudo em instituição registrada, com limite de horas de trabalho."}]'::jsonb, '{}'::jsonb, null);
