insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('emirados-arabes-unidos', 'A residência normalmente é vinculada a um empregador, a um investimento ou a programas específicos. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Residência por emprego","description":"Patrocinada pelo empregador, com contrato registrado."},{"title":"Trabalho remoto (residência virtual)","description":"Para quem trabalha para empresa estrangeira e comprova renda mínima."},{"title":"Golden Visa","description":"Residência longa para investidores, empreendedores e talentos específicos."}]'::jsonb, '{}'::jsonb, null);
insert into tax_models ("country_slug", "model", "description", "source_id", "reference_period", "verified") values ('emirados-arabes-unidos', '{"kind":"flat_estimate","deductionRate":0,"description":"Não há imposto de renda sobre pessoa física assalariada; não considera contribuições específicas de cidadãos.","provenance":{"sourceId":"livora-demo","collectedAt":"2026-10-01","referenceDate":"2026","verified":false,"notes":"Alíquota efetiva demonstrativa; varia com renda, deduções e situação familiar."}}'::jsonb, 'Não há imposto de renda sobre pessoa física assalariada; não considera contribuições específicas de cidadãos.', 'livora-demo', '2026', false);
