insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('republica-tcheca', 'Cidadãos da UE/EEE/Suíça têm livre circulação. Para outros, há autorizações de trabalho e de negócios. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Cartão de empregado","description":"Autorização combinada de residência e trabalho para vagas registradas."},{"title":"Cartão Azul da UE","description":"Para profissionais com diploma e salário mínimo definido."},{"title":"Residência para negócios","description":"Usada por freelancers com licença comercial (živnostenský list)."}]'::jsonb, '{}'::jsonb, null);
