insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('africa-do-sul', 'Vistos de trabalho são concedidos pelo Departamento de Assuntos Internos, com listas de habilidades críticas. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Critical Skills Work Visa","description":"Para profissões listadas como críticas."},{"title":"Visto para trabalho remoto","description":"Para quem trabalha para empresa estrangeira e comprova renda mínima."},{"title":"General Work Visa","description":"Com oferta de emprego e comprovação de que não há candidato local."}]'::jsonb, '{}'::jsonb, null);
