insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('argentina', 'Cidadãos de países do Mercosul e associados têm acesso facilitado à residência. Outras nacionalidades seguem categorias específicas. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Residência Mercosul","description":"Residência temporária e depois permanente para nacionais de países do bloco e associados."},{"title":"Nômade digital","description":"Permanência para trabalhadores remotos de empresas estrangeiras."},{"title":"Estudante","description":"Para cursos em instituições reconhecidas, incluindo universidades públicas."}]'::jsonb, '{"BR":"Brasileiros podem solicitar residência pelo Acordo de Residência do Mercosul."}'::jsonb, null);
