insert into countries ("slug", "name", "iso2", "continent", "currency_code", "languages", "remote_work", "practical") values ('colombia', 'Colômbia', 'CO', 'america-do-sul', 'COP', array['Espanhol']::text[], 'Possui visto para nômades digitais e fuso horário próximo ao do Brasil e dos EUA.', '{"language":"Espanhol é necessário no dia a dia.","health":"Sistema com planos obrigatórios (EPS) e rede privada.","education":"Escolas particulares bilíngues nas grandes cidades.","connectivity":"Boa em bairros como El Poblado e Laureles, em Medellín."}'::jsonb);
insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('colombia', 'A Colômbia emite vistos de visitante, migrante e residente em várias categorias. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Visto de nômade digital","description":"Para trabalhadores remotos e empreendedores digitais com renda mínima."},{"title":"Visto Mercosul","description":"Para nacionais de países do Mercosul."},{"title":"Visto de trabalho","description":"Com contrato de empresa colombiana."}]'::jsonb, '{"BR":"Brasileiros podem se qualificar para o visto Mercosul."}'::jsonb, null);
