insert into immigration_info ("country_slug", "summary", "pathways", "nationality_notes", "last_verified") values ('brasil', 'Brasileiros não precisam de autorização. Estrangeiros precisam de visto ou autorização de residência conforme o objetivo. Os requisitos dependem da sua nacionalidade, do objetivo da estadia e da sua situação individual. Nem todas as pessoas podem trabalhar ou residir legalmente no país.', '[{"title":"Visto temporário para nômade digital","description":"Para estrangeiros que trabalham remotamente para empresas de fora do Brasil."},{"title":"Residência Mercosul","description":"Para nacionais de países do bloco e associados."},{"title":"Autorização de residência para trabalho","description":"Com oferta de empresa brasileira."}]'::jsonb, '{}'::jsonb, null);
