insert into cities ("slug", "name", "country_slug", "lat", "lng", "timezone", "size", "settings", "climate_type", "climate_summary", "summary", "pros", "cons", "tags", "image", "work", "housing", "published") values ('lisboa-portugal', 'Lisboa', 'portugal', 38.7223, -9.1393, 'Europe/Lisbon', 'grande', array['urbano','praia']::text[], 'ameno', 'Verões quentes e secos, invernos suaves e chuvosos.', 'Capital à beira do rio Tejo, com bairros históricos em colinas, praias a menos de uma hora e um ecossistema de tecnologia em crescimento. A língua portuguesa facilita a adaptação de brasileiros.', array['Idioma familiar para brasileiros','Clima ameno e muitas horas de sol','Comunidade internacional e de startups ativa']::text[], array['Aluguéis altos em relação aos salários locais','Burocracia de imigração com prazos longos','Ruas íngremes e transporte lotado nos horários de pico']::text[], array['tendencia','remoto']::text[], '{"url":"https://images.unsplash.com/photo-1585208798174-6cedd86e019a?auto=format&fit=crop&w=1600&q=75","alt":"Bonde amarelo subindo uma rua estreita de Lisboa","credit":"Unsplash","creditUrl":"https://unsplash.com/license"}'::jsonb, '{"demandAreas":["Tecnologia e desenvolvimento de software","Turismo e hotelaria","Atendimento multilíngue (centros de serviços)"],"remoteFriendly":true,"modes":"Presencial e híbrido são comuns em empresas locais; trabalho remoto para empresas estrangeiras é frequente entre imigrantes."}'::jsonb, '{"types":["Apartamentos em prédios antigos (sem elevador em muitos casos)","Apartamentos novos em áreas como Parque das Nações","Quartos em casas partilhadas"],"centerVsOutside":"Morar fora do centro ou em municípios vizinhos (Almada, Amadora, Oeiras) reduz o aluguel, mas aumenta o tempo de deslocamento."}'::jsonb, true);
