insert into articles ("slug", "title", "excerpt", "category", "body", "author", "reading_minutes", "related_destinations", "published_at", "updated_at") values ('quanto-custa-morar-em-outro-pais', 'Quanto custa morar em outro país? Como montar uma estimativa realista', 'Um método passo a passo para estimar seu custo de vida mensal em outra cidade sem cair em armadilhas comuns.', 'financas', '[{"type":"p","text":"Comparar o custo de vida entre países parece simples: basta converter os preços. Na prática, o que muda não é só o preço de cada item, mas também o que você precisa comprar, o que está incluído no salário e como a sua rotina vai se reorganizar."},{"type":"h2","text":"1. Separe custos fixos, variáveis e de instalação"},{"type":"p","text":"Custos fixos são aluguel, contas, internet, transporte e seguro saúde. Variáveis incluem mercado, restaurantes e lazer. Custos de instalação acontecem uma vez: caução do aluguel, móveis, passagens, tradução de documentos e taxas de visto. Misturar os três distorce a estimativa."},{"type":"h2","text":"2. Defina o seu perfil antes de pesquisar preços"},{"type":"p","text":"Uma pessoa sozinha que divide apartamento e cozinha em casa tem um orçamento completamente diferente de uma família que precisa de três quartos perto de uma escola. Escolha um perfil e mantenha-o ao comparar cidades."},{"type":"ul","items":["Quantas pessoas vão morar com você?","Você precisa de carro ou o transporte público resolve?","O seguro saúde é obrigatório para o seu tipo de visto?","Haverá escola particular ou creche?"]},{"type":"h2","text":"3. Converta pelo câmbio, mas pense em renda local"},{"type":"p","text":"Converter preços para reais ajuda a ter noção, mas se você vai receber na moeda local, o que importa é a relação entre o salário local e o custo local. Um café que parece caro em reais pode ser barato para quem ganha em euros."},{"type":"callout","text":"No Partiu Morar, a calculadora de poder de compra faz essa conta de forma transparente: converte sua renda, aplica a estimativa de impostos quando ela existe e mostra quanto sobra."},{"type":"h2","text":"4. Acrescente uma margem de segurança"},{"type":"p","text":"Os primeiros meses costumam ser mais caros: você ainda não conhece os mercados mais baratos, pode morar temporariamente em um lugar mobiliado e terá gastos inesperados com documentação. Planeje uma margem extra para esse período."}]'::jsonb, 'Equipe editorial Partiu Morar', 7, array['lisboa-portugal','madrid-espanha','bangkok-tailandia']::text[], '2026-10-01', '2026-10-01');
insert into articles ("slug", "title", "excerpt", "category", "body", "author", "reading_minutes", "related_destinations", "published_at", "updated_at") values ('destinos-para-profissionais-de-tecnologia', 'Como escolher um destino sendo profissional de tecnologia', 'Critérios para avaliar cidades quando sua carreira é em software, dados ou produto — além do salário bruto.', 'carreira', '[{"type":"p","text":"Profissionais de tecnologia costumam ter mais opções de mobilidade, mas isso não significa que qualquer destino funcione. Vale olhar para o ecossistema, para as regras de visto e para o que sobra no fim do mês."},{"type":"h2","text":"Ecossistema e idioma de trabalho"},{"type":"p","text":"Algumas cidades concentram empresas que contratam em inglês, o que reduz a barreira inicial. Em outras, o idioma local é necessário mesmo em vagas técnicas. Pesquise vagas reais nos portais de emprego do país para entender o que é exigido."},{"type":"h2","text":"Visto vinculado ao empregador ou independente"},{"type":"p","text":"Em vários países, o visto de trabalho depende do empregador. Trocar de emprego pode exigir novo processo. Programas por pontos ou de residência permanente oferecem mais liberdade, mas costumam ser mais longos."},{"type":"h2","text":"Salário líquido, não bruto"},{"type":"p","text":"Impostos e contribuições variam muito. Um salário bruto alto em um país com tributação elevada pode render menos do que um salário menor em outro lugar. Compare sempre o líquido estimado contra o custo de vida."},{"type":"ul","items":["Leia o contrato com atenção a benefícios como seguro saúde e previdência.","Verifique se existe regime fiscal especial para recém-chegados.","Considere o custo de moradia perto do escritório, se o trabalho for presencial."]},{"type":"h2","text":"Trabalho remoto como alternativa"},{"type":"p","text":"Se você já trabalha remotamente, vistos para nômades digitais podem permitir morar em cidades com custo de vida menor. Confira as regras de tributação: em geral, quem passa a residir em um país pode se tornar residente fiscal lá."}]'::jsonb, 'Equipe editorial Partiu Morar', 6, array['berlim-alemanha','lisboa-portugal','toronto-canada']::text[], '2026-10-01', '2026-10-01');
insert into articles ("slug", "title", "excerpt", "category", "body", "author", "reading_minutes", "related_destinations", "published_at", "updated_at") values ('como-planejar-uma-mudanca-internacional', 'Como planejar uma mudança internacional em etapas', 'Um roteiro organizado, da pesquisa inicial aos primeiros meses no novo país.', 'planejamento', '[{"type":"p","text":"Mudar de país envolve decisões financeiras, legais e emocionais ao mesmo tempo. Dividir o processo em etapas ajuda a não esquecer nada importante."},{"type":"h2","text":"Etapa 1: pesquisa e escolha"},{"type":"ul","items":["Liste de três a cinco destinos possíveis.","Compare custo de vida, salário e caminhos de visto para cada um.","Visite, se possível, antes de decidir."]},{"type":"h2","text":"Etapa 2: caminho legal"},{"type":"p","text":"Identifique qual visto ou autorização se aplica a você. Consulte sempre o site oficial do governo ou do consulado; regras mudam e intermediários nem sempre estão atualizados."},{"type":"h2","text":"Etapa 3: documentos"},{"type":"ul","items":["Passaporte válido com folga.","Certidões (nascimento, casamento) com apostila de Haia quando exigido.","Diplomas e históricos, com tradução juramentada se necessário.","Antecedentes criminais."]},{"type":"h2","text":"Etapa 4: finanças"},{"type":"p","text":"Monte uma reserva para os primeiros meses, entenda como transferir dinheiro com custos baixos e verifique suas obrigações fiscais no Brasil ao sair do país, como a comunicação de saída definitiva."},{"type":"h2","text":"Etapa 5: chegada"},{"type":"ul","items":["Registro de residência e número fiscal local.","Conta bancária.","Cadastro no sistema de saúde.","Moradia definitiva, depois de conhecer os bairros."]},{"type":"callout","text":"Use a checklist de mudança na área de Favoritos para acompanhar cada etapa."}]'::jsonb, 'Equipe editorial Partiu Morar', 8, array[]::text[], '2026-10-01', '2026-10-01');
insert into articles ("slug", "title", "excerpt", "category", "body", "author", "reading_minutes", "related_destinations", "published_at", "updated_at") values ('como-comparar-salarios-entre-paises', 'Como comparar salários entre países sem se enganar', 'Bruto, líquido, número de salários por ano e benefícios: o que observar ao comparar propostas.', 'financas', '[{"type":"p","text":"Duas propostas com o mesmo valor convertido podem significar padrões de vida muito diferentes. Antes de comparar, coloque os números na mesma base."},{"type":"h2","text":"Anual ou mensal? Quantos salários por ano?"},{"type":"p","text":"Alguns países pagam 12 salários por ano; outros, como Portugal e Espanha, podem pagar 14, incluindo subsídios de férias e de Natal. Nos países de língua inglesa é comum informar o salário anual. Converta tudo para a mesma referência."},{"type":"h2","text":"Bruto não é líquido"},{"type":"p","text":"Impostos sobre a renda e contribuições sociais podem consumir uma parte significativa do salário bruto, e a proporção muda com a faixa de renda e a situação familiar. Use simuladores oficiais do país quando disponíveis."},{"type":"h2","text":"Benefícios que valem dinheiro"},{"type":"ul","items":["Seguro saúde pago pela empresa.","Previdência complementar.","Vale-refeição ou ajuda de custo de transporte.","Auxílio de relocação."]},{"type":"h2","text":"Compare com o custo de vida local"},{"type":"p","text":"O indicador mais útil é quanto sobra depois das despesas. É isso que define sua capacidade de poupar e de lidar com imprevistos."}]'::jsonb, 'Equipe editorial Partiu Morar', 6, array[]::text[], '2026-10-01', '2026-10-01');
insert into articles ("slug", "title", "excerpt", "category", "body", "author", "reading_minutes", "related_destinations", "published_at", "updated_at") values ('antes-de-aceitar-um-emprego-no-exterior', 'O que considerar antes de aceitar um emprego no exterior', 'Perguntas para fazer ao empregador e a si mesmo antes de assinar um contrato em outro país.', 'carreira', '[{"type":"p","text":"Uma oferta de emprego no exterior é empolgante, mas o contrato define muito da sua vida nos primeiros anos. Faça as perguntas certas antes de aceitar."},{"type":"h2","text":"Perguntas para o empregador"},{"type":"ul","items":["A empresa patrocina o visto e paga as taxas?","Há ajuda de relocação ou moradia temporária?","Qual o período de experiência e o que acontece com o visto se o contrato terminar?","O salário informado é bruto anual, bruto mensal ou líquido?"]},{"type":"h2","text":"Perguntas para você"},{"type":"ul","items":["Esse salário cobre o custo de vida da cidade com folga?","Você está preparado para a adaptação cultural e o idioma?","Sua família, se for junto, terá direito a trabalhar ou estudar?"]},{"type":"callout","text":"Desconfie de ofertas que pedem pagamento antecipado para garantir a vaga ou o visto."}]'::jsonb, 'Equipe editorial Partiu Morar', 5, array[]::text[], '2026-10-01', '2026-10-01');
insert into articles ("slug", "title", "excerpt", "category", "body", "author", "reading_minutes", "related_destinations", "published_at", "updated_at") values ('reserva-financeira-para-mudar-de-pais', 'Como organizar uma reserva financeira para mudar de país', 'Quais gastos entram na conta da mudança e como dimensionar a reserva para os primeiros meses.', 'planejamento', '[{"type":"p","text":"A reserva para a mudança não é a mesma coisa que a reserva de emergência. Ela precisa cobrir os custos de instalação e o período até a sua renda se estabilizar no novo país."},{"type":"h2","text":"O que entra na conta"},{"type":"ul","items":["Taxas de visto, documentos, traduções e apostilamentos.","Passagens e envio de bagagem.","Moradia temporária nas primeiras semanas.","Caução e primeiros aluguéis do imóvel definitivo.","Móveis e itens básicos de casa.","Custo de vida mensal até receber o primeiro salário."]},{"type":"h2","text":"Quanto tempo de custo de vida guardar"},{"type":"p","text":"Depende de você já ter emprego garantido ou não. Quem chega sem trabalho precisa de uma reserva para mais meses do que quem já tem contrato assinado. Alguns vistos exigem comprovação de meios financeiros mínimos; confira o valor no site oficial."},{"type":"h2","text":"Câmbio e transferências"},{"type":"p","text":"Compare o custo total das transferências internacionais, somando tarifa e spread do câmbio. A cotação de referência que você vê em sites e no Partiu Morar não é a que o banco vai aplicar."}]'::jsonb, 'Equipe editorial Partiu Morar', 6, array[]::text[], '2026-10-01', '2026-10-01');
